"""
Inception 42 Jais-3-0.9B-Chat Sovereign LLM Runner (Phase 17).
Integrates Inception 42's flagship sovereign Arabic-English bilingual model
(inception42/Jais-3-0.9B-Chat) for clinical and frontline early-warning dispatches.
"""

from __future__ import annotations

import logging
from dataclasses import dataclass
from typing import Any, Dict, List, Optional

logger = logging.getLogger(__name__)


@dataclass
class JaisGenerationResult:
    """Output generated by Inception 42 Jais model."""
    raw_response: str
    cleaned_narrative: str
    model_id: str
    execution_mode: str  # "JAIS_NATIVE_TORCH" or "JAIS_VERIFIED_TEMPLATE"
    device: str
    passed_fenced_gate: bool
    unverified_tokens: List[float]


class JaisInferenceRunner:
    """
    Wrapper for Inception 42's Jais-3-0.9B-Chat foundational language model.
    Supports GPU-accelerated local inference (torch.float16, device_map="auto")
    with deterministic fallback for air-gapped demo environments.
    """

    DEFAULT_MODEL_ID = "inception42/Jais-3-0.9B"

    def __init__(self, model_id: str = DEFAULT_MODEL_ID):
        self.model_id = model_id
        self._tokenizer = None
        self._model = None
        self._is_loaded = False
        self._device = "cpu"

    def try_load_model(self, allow_network: bool = False) -> bool:
        """Attempts to load tokenizer and weights from local cache or HuggingFace."""
        if self._is_loaded:
            return True

        try:
            import torch
            from transformers import AutoModelForCausalLM, AutoTokenizer

            # First try loading strictly from local cache to prevent network retry timeouts
            try:
                self._tokenizer = AutoTokenizer.from_pretrained(
                    self.model_id,
                    local_files_only=True,
                    trust_remote_code=True,
                )
                local_only = True
            except Exception:
                if not allow_network:
                    # If network not enabled and not in local cache, gracefully fall back immediately
                    self._is_loaded = False
                    return False
                local_only = False
                self._tokenizer = AutoTokenizer.from_pretrained(
                    self.model_id,
                    local_files_only=False,
                    trust_remote_code=True,
                )

            # Check CUDA availability
            if torch.cuda.is_available():
                self._device = "cuda:0"
                dtype = torch.float16
            else:
                self._device = "cpu"
                dtype = torch.float32

            self._model = AutoModelForCausalLM.from_pretrained(
                self.model_id,
                dtype=dtype,
                device_map="auto" if torch.cuda.is_available() else None,
                local_files_only=local_only,
                trust_remote_code=True,
            )
            self._is_loaded = True
            logger.info("Inception 42 Jais model loaded successfully on %s", self._device)
            return True
        except Exception as e:
            logger.info("Jais model weights not locally cached: %s. Using verified template engine.", e)
            self._is_loaded = False
            return False

    def generate_bilingual_dispatch(
        self,
        alert_dict: Dict[str, Any],
        max_tokens: int = 160,
    ) -> JaisGenerationResult:
        """
        Generates an Arabic-English bilingual early warning dispatch.
        Attempts native Jais inference on GPU; falls back to deterministic template if weights are not local.
        """
        from prahari.llm.fenced_validator import FencedHallucinationGate

        site_name = alert_dict.get("site_name", "Jebel Ali Industrial Yard")
        site_id = alert_dict.get("site_id", "SITE-JA-01")
        tier = alert_dict.get("tier", "Warning")
        prob_pct = round(alert_dict.get("calibrated_p", 0.833) * 100.0, 1)
        wbgt_val = round(alert_dict.get("wbgt", 33.4), 1)

        # Structure bilingual prompt aligned with Inception 42 conventions
        user_prompt = (
            f"Generate an emergency bilingual heat alert in Arabic and English for {site_name}. "
            f"Alert Tier: {tier} ({prob_pct}% probability). Current WBGT: {wbgt_val}°C. "
            f"Mandate: UAE MOHRE Ministerial Resolution No. 44 of 2022 (mandatory 15-minute shaded rest and hydration)."
        )

        messages = [
            {
                "role": "system",
                "content": (
                    "You are Munzir Early Warning Engine, an official occupational health and environmental safety system for the UAE. "
                    "Generate concise, authoritative bilingual operational alerts in Arabic and English for frontline site supervisors. "
                    "Strictly adhere to the provided telemetry and UAE MOHRE Ministerial Resolution No. 44 of 2022."
                ),
            },
            {"role": "user", "content": user_prompt},
        ]

        fenced_gate = FencedHallucinationGate()

        if self.try_load_model() and self._tokenizer is not None and self._model is not None:
            try:
                import torch
                prompt = self._tokenizer.apply_chat_template(
                    messages,
                    tokenize=False,
                    add_generation_prompt=True,
                    reasoning_effort="low",
                )
                inputs = self._tokenizer(prompt, return_tensors="pt").to(self._model.device)
                with torch.no_grad():
                    outputs = self._model.generate(
                        **inputs,
                        max_new_tokens=max(max_tokens, 150),
                        do_sample=True,
                        temperature=0.3,
                        pad_token_id=self._tokenizer.eos_token_id,
                    )
                # Decode newly generated tokens only
                gen_tokens = outputs[0][inputs["input_ids"].shape[-1]:]
                raw_text = self._tokenizer.decode(gen_tokens, skip_special_tokens=False)

                # Extract content after reasoning block if model uses reasoning tags
                if "</ifm|think_faster>" in raw_text:
                    cleaned_text = raw_text.split("</ifm|think_faster>")[-1]
                elif "</ifm|think>" in raw_text:
                    cleaned_text = raw_text.split("</ifm|think>")[-1]
                else:
                    cleaned_text = raw_text
                cleaned_text = cleaned_text.replace("<|ifm|im_end|>", "").strip()

                is_valid, unverified = fenced_gate.verify_narrative(cleaned_text, alert_dict)
                if is_valid and len(cleaned_text) > 30:
                    return JaisGenerationResult(
                        raw_response=raw_text,
                        cleaned_narrative=cleaned_text,
                        model_id=self.model_id,
                        execution_mode="JAIS_NATIVE_TORCH",
                        device=str(self._model.device),
                        passed_fenced_gate=True,
                        unverified_tokens=[],
                    )
                logger.info(
                    "Jais native output contained unverified tokens (%s). Falling back to verified template.",
                    unverified,
                )
            except Exception as e:
                logger.warning("Inference execution failed: %s. Falling back to template.", e)

        # Deterministic Verified Fallback Template (Zero Hallucination Guaranteed)
        arabic_text = (
            f"تنبيه وقائي من منصة منذر ({tier}): رصد خطر إجهاد حراري في {site_name} بنسبة {prob_pct}٪ "
            f"مع بلوغ مؤشر الحرارة الرطبة {wbgt_val} درجة مئوية. "
            f"بموجب قرار وزارة الموارد البشرية والتوطين رقم ٤٤ لسنة ٢٠٢٢، يجب تطبيق فترات راحة مظللة وتوفير محطات ترطيب فوراً."
        )
        english_text = (
            f"MUNZIR ALERT ({tier}): Thermal stress risk detected at {site_name} with {prob_pct}% probability "
            f"(Peak WBGT: {wbgt_val}°C). In accordance with UAE MOHRE Ministerial Resolution No. 44 of 2022, "
            f"mandatory 15-minute shaded rest rotations and chilled electrolyte stations are immediately active."
        )

        combined = f"{arabic_text}\n\n{english_text}"
        is_valid, unverified = fenced_gate.verify_narrative(combined, alert_dict)

        return JaisGenerationResult(
            raw_response=combined,
            cleaned_narrative=combined,
            model_id=self.model_id,
            execution_mode="JAIS_VERIFIED_TEMPLATE",
            device=self._device,
            passed_fenced_gate=is_valid,
            unverified_tokens=unverified,
        )


_GLOBAL_JAIS_RUNNER: Optional[JaisInferenceRunner] = None


def get_jais_runner(model_id: str = JaisInferenceRunner.DEFAULT_MODEL_ID) -> JaisInferenceRunner:
    """Returns singleton JaisInferenceRunner instance to avoid reloading weights into GPU VRAM."""
    global _GLOBAL_JAIS_RUNNER
    if _GLOBAL_JAIS_RUNNER is None or _GLOBAL_JAIS_RUNNER.model_id != model_id:
        _GLOBAL_JAIS_RUNNER = JaisInferenceRunner(model_id=model_id)
    return _GLOBAL_JAIS_RUNNER

